arguments.command:
python3 -c '
import json
from pathlib import Path
from collections import defaultdict

run = Path("/workspace/observed_run")
traces = [json.loads(line) for line in (run / "tool_traces.jsonl").read_text().splitlines()]
req = [json.loads(line) for line in (run / "request_traces.jsonl").read_text().splitlines()]

events_by_traj = defaultdict(list)
for t in traces:
    events_by_traj[t["trajectory_id"]].append(t)

# Initial requests have the full trajectory_ids for each batch
for r in req:
    if r["phase"] == "initial":
        print("==========================================")
        print("INIT REQ", r["request_index"], "step=", r["step"], "mode=", r["mode"], "n_trajs=", len(r["trajectory_ids"]))
        for row, tid in enumerate(r["trajectory_ids"]):
            evs = events_by_traj[tid]
            case_id = evs[0]["case_id"]
            grade = [e for e in evs if e["event"] == "grade"][0]
            rew = grade["reward"]
            run_tests_evs = [e["passed"] for e in evs if e["event"] == "run_tests"]
            if rew > 0 or True in run_tests_evs:
                print("  Row", row, "grp", row//4, "case=", case_id, "rew=", rew, "run_tests_passed=", run_tests_evs)
                for e in evs:
                    if e["event"] not in ("reset",):
                        if e["event"] == "replace_source":
                            print("    call", e["call"], "replace_source: old=", repr(e["old"][:40]), "new=", repr(e["new"][:40]), "->", e["result"])
                        elif e["event"] == "run_tests":
                            print("    call", e["call"], "run_tests: passed=", e["passed"])
                        elif e["event"] == "grade":
                            print("    grade: reward=", e["reward"], "passed=", e["passed"])
                        else:
                            print("    call", e["call"], e["event"])
'

